from __future__ import annotations

import threading
from typing import Any, Callable

from insight_specialist_backend.model_client import ModelClient
from insight_specialist_backend.runs import InMemoryRunStore, RunNotFoundError, RunSnapshot
from insight_specialist_backend.schemas.question_clarification import QuestionClarificationSpec
from insight_specialist_backend.schemas.validation import SchemaValidationError
from insight_specialist_backend.stages.question_clarification import QuestionClarificationStage
from insight_specialist_backend.stages.question_interpretation import QuestionInterpretationStage


ModelClientFactory = Callable[[], ModelClient]


class QuestionClarificationRunService:
    def __init__(
        self,
        store: InMemoryRunStore,
        model_client_factory: ModelClientFactory,
    ) -> None:
        self.store = store
        self.model_client_factory = model_client_factory

    def start_run(self, raw_question: str, dataset_profile: dict[str, Any]) -> RunSnapshot:
        snapshot = self.store.create_run(
            "question_clarification",
            {
                "raw_question": raw_question,
                "dataset_profile": dataset_profile,
            },
        )
        self.store.append_context_entry(
            snapshot.run_id,
            step="define_question",
            actor="user",
            entry_type="analysis_request",
            content={
                "raw_question": raw_question,
                "dataset_profile": dataset_profile,
            },
        )
        thread = threading.Thread(
            target=self._execute_run,
            args=(snapshot.run_id, raw_question, dataset_profile),
            daemon=True,
            name=f"question-clarification-{snapshot.run_id[:8]}",
        )
        thread.start()
        return snapshot

    def submit_clarification_answers(self, run_id: str, answers: dict[str, str]) -> RunSnapshot:
        snapshot = self.store.get_run(run_id)
        if snapshot.result is None or "spec" not in snapshot.result:
            raise SchemaValidationError("Run does not have a question clarification result yet")

        clarification_spec = QuestionClarificationSpec.from_dict(snapshot.result["spec"])
        _validate_blocking_answers(clarification_spec, answers)

        accepted_answers = {key: answers[key].strip() for key in answers}
        updated_clarification = {
            **clarification_spec.to_dict(),
            "accepted_answers": accepted_answers,
        }
        updated_result = {
            **snapshot.result,
            "spec": updated_clarification,
        }
        self.store.update_result(run_id, updated_result)
        self.store.append_context_entry(
            run_id,
            step="clarify_intent",
            actor="user",
            entry_type="clarification_answers",
            content={"answers": accepted_answers},
        )
        self.store.append_event(
            run_id,
            "clarification_answers_received",
            {
                "stage": "question_clarification",
                "answer_count": len(accepted_answers),
            },
        )
        self.store.mark_running(run_id)

        thread = threading.Thread(
            target=self._execute_question_interpretation,
            args=(run_id,),
            daemon=True,
            name=f"question-interpretation-{run_id[:8]}",
        )
        thread.start()
        return self.store.get_run(run_id)

    def _execute_run(
        self,
        run_id: str,
        raw_question: str,
        dataset_profile: dict[str, Any],
    ) -> None:
        self.store.mark_running(run_id)
        self.store.append_event(
            run_id,
            "stage_started",
            {
                "stage": "question_clarification",
                "label": "Question clarification",
            },
        )
        self.store.append_event(
            run_id,
            "model_call_started",
            {
                "stage": "question_clarification",
                "model_call_count": 1,
            },
        )

        try:
            result = QuestionClarificationStage(self.model_client_factory()).run(
                raw_question,
                dataset_profile,
            )
        except Exception as error:
            self.store.append_event(
                run_id,
                "stage_failed",
                {
                    "stage": "question_clarification",
                    "error": str(error),
                },
            )
            self.store.mark_failed(run_id, str(error))
            return

        result_dict = result.to_dict()
        self.store.append_context_entry(
            run_id,
            step="clarify_intent",
            actor="assistant",
            entry_type="question_clarification",
            content=result_dict,
        )
        self.store.append_event(
            run_id,
            "model_call_succeeded",
            {
                "stage": "question_clarification",
                "model": result_dict.get("model"),
                "usage": result_dict.get("usage"),
                "model_call_count": 1,
            },
        )
        self.store.append_event(
            run_id,
            "stage_succeeded",
            {
                "stage": "question_clarification",
                "should_ask_user": result.spec.should_ask_user,
                "blocking_question_count": len(
                    [question for question in result.spec.unanswered_questions if question.blocking]
                ),
            },
        )
        self.store.mark_succeeded(run_id, result_dict)

    def _execute_question_interpretation(self, run_id: str) -> None:
        snapshot = self.store.get_run(run_id)
        if snapshot.result is None:
            self.store.mark_failed(run_id, "Run does not have a question clarification result")
            return

        self.store.append_event(
            run_id,
            "stage_started",
            {
                "stage": "question_interpretation",
                "label": "Question interpretation",
            },
        )
        self.store.append_event(
            run_id,
            "model_call_started",
            {
                "stage": "question_interpretation",
                "model_call_count": _model_call_count(self.store.context_entries(run_id)) + 1,
            },
        )

        try:
            result = QuestionInterpretationStage(self.model_client_factory()).run(
                raw_question=str(snapshot.input["raw_question"]),
                dataset_profile=dict(snapshot.input["dataset_profile"]),
                question_clarification=dict(snapshot.result["spec"]),
                process_context=[entry.to_dict() for entry in self.store.context_entries(run_id)],
            )
        except Exception as error:
            self.store.append_event(
                run_id,
                "stage_failed",
                {
                    "stage": "question_interpretation",
                    "error": str(error),
                },
            )
            self.store.mark_failed(run_id, str(error))
            return

        interpretation_dict = result.to_dict()
        self.store.append_context_entry(
            run_id,
            step="interpret_question",
            actor="assistant",
            entry_type="question_spec",
            content=interpretation_dict,
        )
        current = self.store.get_run(run_id).result or {}
        updated_result = {
            **current,
            "question_interpretation": interpretation_dict,
        }
        self.store.update_result(run_id, updated_result)
        self.store.append_event(
            run_id,
            "model_call_succeeded",
            {
                "stage": "question_interpretation",
                "model": interpretation_dict.get("model"),
                "usage": interpretation_dict.get("usage"),
                "model_call_count": _model_call_count(self.store.context_entries(run_id)),
            },
        )
        self.store.append_event(
            run_id,
            "stage_succeeded",
            {
                "stage": "question_interpretation",
                "analysis_intent": result.spec.analysis_intent,
                "target_candidates": result.spec.target_candidates,
            },
        )
        self.store.mark_succeeded(run_id, updated_result)


def _validate_blocking_answers(spec: QuestionClarificationSpec, answers: dict[str, str]) -> None:
    blocking_ids = {question.id for question in spec.unanswered_questions if question.blocking}
    missing = sorted(question_id for question_id in blocking_ids if not answers.get(question_id, "").strip())
    if missing:
        raise SchemaValidationError(f"Missing answers for blocking clarification questions: {', '.join(missing)}")
    unknown = sorted(question_id for question_id in answers if question_id not in spec.unanswered_question_ids)
    if unknown:
        raise SchemaValidationError(f"Unknown clarification answer ids: {', '.join(unknown)}")


def _model_call_count(context_entries: list[Any]) -> int:
    return len(
        [
            entry
            for entry in context_entries
            if getattr(entry, "actor", None) == "assistant"
            and getattr(entry, "entry_type", None) in {"question_clarification", "question_spec"}
        ]
    )

from __future__ import annotations

from typing import Any

from fastapi import FastAPI, Header, HTTPException, Query
from pydantic import BaseModel, Field
from starlette.middleware.cors import CORSMiddleware
from starlette.responses import StreamingResponse

from insight_specialist_backend import __version__
from insight_specialist_backend.config import ModelEndpointConfig
from insight_specialist_backend.model_client import ModelClient, ModelClientError
from insight_specialist_backend.question_clarification_runs import QuestionClarificationRunService
from insight_specialist_backend.runs import InMemoryRunStore, RunNotFoundError, iter_sse_events
from insight_specialist_backend.schemas.validation import SchemaValidationError
from insight_specialist_backend.stages.question_clarification import QuestionClarificationStage


LOCAL_FRONTEND_ORIGIN_REGEX = (
    r"^(http://(127\.0\.0\.1|localhost)(:\d+)?|http://tauri\.localhost|tauri://localhost)$"
)

app = FastAPI(title="Insight Specialist Local Backend", version=__version__)
app.add_middleware(
    CORSMiddleware,
    allow_origin_regex=LOCAL_FRONTEND_ORIGIN_REGEX,
    allow_methods=["GET", "POST", "OPTIONS"],
    allow_headers=["content-type", "last-event-id"],
)
run_store = InMemoryRunStore()
question_clarification_runs = QuestionClarificationRunService(run_store, lambda: _client())


class ChatMessage(BaseModel):
    role: str = Field(pattern="^(system|user|assistant|tool)$")
    content: str


class ChatRequest(BaseModel):
    messages: list[ChatMessage]
    temperature: float | None = None
    max_tokens: int | None = None


class QuestionClarificationRequest(BaseModel):
    raw_question: str
    dataset_profile: dict[str, Any]


class ClarificationAnswersRequest(BaseModel):
    answers: dict[str, str]


def _client() -> ModelClient:
    return ModelClient(ModelEndpointConfig.from_env())


@app.get("/health")
def health() -> dict[str, str]:
    return {"status": "ok", "service": "insight-specialist-backend", "version": __version__}


@app.get("/settings/model-endpoint")
def model_endpoint() -> dict[str, Any]:
    return ModelEndpointConfig.from_env().public_dict()


@app.get("/llm/models")
def llm_models() -> dict[str, Any]:
    try:
        return _client().list_models()
    except ModelClientError as error:
        raise HTTPException(status_code=502, detail=str(error)) from error


@app.post("/llm/chat")
def llm_chat(request: ChatRequest) -> dict[str, Any]:
    try:
        result = _client().chat_completion(
            [message.model_dump() for message in request.messages],
            temperature=request.temperature,
            max_tokens=request.max_tokens,
        )
    except ModelClientError as error:
        raise HTTPException(status_code=502, detail=str(error)) from error
    return {
        "content": result.content,
        "usage": result.raw_response.get("usage"),
        "model": result.raw_response.get("model"),
        "raw_response": result.raw_response,
    }


@app.post("/llm/smoke-test")
def llm_smoke_test() -> dict[str, Any]:
    try:
        result = _client().smoke_test()
    except ModelClientError as error:
        raise HTTPException(status_code=502, detail=str(error)) from error
    return {
        "status": "ok" if result.content.strip() == "local-backend-llm-ok" else "unexpected_response",
        "content": result.content,
        "usage": result.raw_response.get("usage"),
        "model": result.raw_response.get("model"),
    }


@app.post("/stages/question-clarification")
def question_clarification(request: QuestionClarificationRequest) -> dict[str, Any]:
    try:
        return QuestionClarificationStage(_client()).run(
            request.raw_question,
            request.dataset_profile,
        ).to_dict()
    except (ModelClientError, SchemaValidationError) as error:
        raise HTTPException(status_code=502, detail=str(error)) from error


@app.post("/runs/question-clarification", status_code=202)
def create_question_clarification_run(request: QuestionClarificationRequest) -> dict[str, Any]:
    snapshot = question_clarification_runs.start_run(
        request.raw_question,
        request.dataset_profile,
    )
    return {
        **snapshot.to_dict(),
        "run_url": f"/runs/{snapshot.run_id}",
        "events_url": f"/runs/{snapshot.run_id}/events",
    }


@app.get("/runs/{run_id}")
def get_run(run_id: str) -> dict[str, Any]:
    try:
        return run_store.get_run(run_id).to_dict()
    except RunNotFoundError as error:
        raise HTTPException(status_code=404, detail=f"Unknown run: {run_id}") from error


@app.post("/runs/{run_id}/clarification-answers", status_code=202)
def submit_clarification_answers(run_id: str, request: ClarificationAnswersRequest) -> dict[str, Any]:
    try:
        snapshot = question_clarification_runs.submit_clarification_answers(
            run_id,
            request.answers,
        )
    except RunNotFoundError as error:
        raise HTTPException(status_code=404, detail=f"Unknown run: {run_id}") from error
    except SchemaValidationError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    return {
        **snapshot.to_dict(),
        "run_url": f"/runs/{snapshot.run_id}",
        "events_url": f"/runs/{snapshot.run_id}/events",
    }


@app.get("/runs/{run_id}/events")
def get_run_events(
    run_id: str,
    after: int = Query(default=0, ge=0),
    last_event_id: str | None = Header(default=None, alias="Last-Event-ID"),
) -> StreamingResponse:
    try:
        run_store.get_run(run_id)
    except RunNotFoundError as error:
        raise HTTPException(status_code=404, detail=f"Unknown run: {run_id}") from error

    after_id = after
    if last_event_id is not None:
        try:
            after_id = int(last_event_id)
        except ValueError as error:
            raise HTTPException(status_code=400, detail="Last-Event-ID must be an integer") from error

    return StreamingResponse(
        iter_sse_events(run_store, run_id, after_id=after_id),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
        },
    )

import { invoke } from "@tauri-apps/api/core";
import type {
  ClarificationAnswersPayload,
  QuestionClarificationPayload,
  RunControlResponse,
  RunSnapshot,
  RunStartResponse,
} from "./insight-specialist-api.types";

const API_PREFIX = "/api";
const TAURI_BACKEND_URL_COMMAND = "get_backend_url";

let backendBaseUrl: string | null = null;
let backendBaseUrlPromise: Promise<string> | null = null;

export async function startQuestionClarificationRun(
  payload: QuestionClarificationPayload,
  fetchImpl: typeof fetch = fetch,
): Promise<RunStartResponse> {
  const url = await toResolvedApiUrl("/runs/question-clarification");
  const response = await fetchBackend(url, fetchImpl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return decodeJsonResponse<RunStartResponse>(response);
}

export async function getRunSnapshot(
  runUrl: string,
  fetchImpl: typeof fetch = fetch,
): Promise<RunSnapshot> {
  const url = await toResolvedApiUrl(runUrl);
  const response = await fetchBackend(url, fetchImpl);
  return decodeJsonResponse<RunSnapshot>(response);
}

export async function submitClarificationAnswers(
  runId: string,
  payload: ClarificationAnswersPayload,
  fetchImpl: typeof fetch = fetch,
): Promise<RunControlResponse> {
  const url = await toResolvedApiUrl(`/runs/${runId}/clarification-answers`);
  const response = await fetchBackend(url, fetchImpl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return decodeJsonResponse<RunControlResponse>(response);
}

export async function toResolvedApiUrl(path: string): Promise<string> {
  return toApiUrl(path, await resolveApiBaseUrl());
}

export async function resolveApiBaseUrl(): Promise<string> {
  if (!isTauriRuntime()) return API_PREFIX;

  if (!backendBaseUrlPromise) {
    backendBaseUrlPromise = invoke<string>(TAURI_BACKEND_URL_COMMAND).then(normalizeBackendBaseUrl);
  }
  backendBaseUrl = await backendBaseUrlPromise;
  return backendBaseUrl;
}

export function toApiUrl(path: string, baseUrl = backendBaseUrl ?? API_PREFIX): string {
  if (isAbsoluteUrl(path)) return path;

  const normalizedBaseUrl = normalizeBackendBaseUrl(baseUrl);
  let normalizedPath = path.startsWith("/") ? path : `/${path}`;

  if (normalizedBaseUrl === API_PREFIX) {
    if (normalizedPath === API_PREFIX || normalizedPath.startsWith(`${API_PREFIX}/`)) return normalizedPath;
    return `${API_PREFIX}${normalizedPath}`;
  }

  if (normalizedPath === API_PREFIX) return normalizedBaseUrl;
  if (normalizedPath.startsWith(`${API_PREFIX}/`)) {
    normalizedPath = normalizedPath.slice(API_PREFIX.length);
  }
  return `${normalizedBaseUrl}${normalizedPath}`;
}

export function isTauriRuntime(runtime: unknown = globalThis): boolean {
  return Boolean((runtime as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__);
}

export function clearBackendUrlCache(): void {
  backendBaseUrl = null;
  backendBaseUrlPromise = null;
}

async function decodeJsonResponse<T>(response: Response): Promise<T> {
  let body: unknown;
  try {
    body = await response.json();
  } catch {
    body = undefined;
  }

  if (!response.ok) {
    const detail = body && typeof body === "object" && "detail" in body ? String(body.detail) : response.statusText;
    throw new Error(detail || `Request failed with HTTP ${response.status}`);
  }

  return body as T;
}

async function fetchBackend(
  url: string,
  fetchImpl: typeof fetch,
  init?: RequestInit,
): Promise<Response> {
  try {
    return await fetchImpl(url, init);
  } catch (error) {
    const detail = error instanceof Error && error.message ? ` ${error.message}` : "";
    throw new Error(`Local backend is not reachable at ${describeBackendTarget(url)}.${detail}`);
  }
}

function normalizeBackendBaseUrl(value: string): string {
  const trimmed = value.trim().replace(/\/+$/, "");
  if (!trimmed) throw new Error("Backend URL discovery returned an empty URL.");
  return trimmed;
}

function describeBackendTarget(url: string): string {
  if (url.startsWith(API_PREFIX)) return "the Vite /api proxy";
  try {
    return new URL(url).origin;
  } catch {
    return url;
  }
}

function isAbsoluteUrl(path: string): boolean {
  return /^[a-z][a-z\d+\-.]*:\/\//i.test(path);
}

import type { DatasetProfile } from "../data/dataset-profile.types";
import type { ClarificationAnswers } from "../workflow/workflow.types";

export interface QuestionClarificationPayload {
  raw_question: string;
  dataset_profile: DatasetProfile;
}

export interface ClarificationAnswersPayload {
  answers: ClarificationAnswers;
}

export interface RunEvent {
  id: number;
  run_id: string;
  type: string;
  timestamp: string;
  payload: Record<string, unknown>;
}

export interface RunStartResponse {
  run_id: string;
  kind: string;
  status: string;
  created_at: string;
  updated_at: string;
  input: QuestionClarificationPayload;
  event_count: number;
  run_url: string;
  events_url: string;
}

export interface ClarificationQuestion {
  id: string;
  question: string;
  reason: string;
  blocking: boolean;
}

export interface ClarificationDefault {
  field: string;
  default: string;
  reason: string;
}

export interface QuestionClarificationSpec {
  raw_question: string;
  framework: string;
  analysis_goal: string;
  known_inputs: {
    dataset_available: boolean;
    candidate_outcome_columns: string[];
    candidate_time_columns: string[];
  };
  unanswered_questions: ClarificationQuestion[];
  non_blocking_defaults: ClarificationDefault[];
  should_ask_user: boolean;
  can_proceed_to_interpretation: boolean;
  reasoning_summary: string;
}

export interface QuestionClarificationResult {
  spec: QuestionClarificationSpec;
  model?: string;
  usage?: Record<string, unknown>;
  question_interpretation?: QuestionInterpretationResult;
}

export interface QuestionSpec {
  raw_question: string;
  analysis_intent: string;
  target_candidates: string[];
  outcome_type: string;
  key_columns: string[];
  leakage_or_timing_review_columns: string[];
  user_language_is_causal: boolean;
  preferred_user_facing_language: string;
  external_context_need_likelihood_1_to_100: number;
  reasoning_summary: string;
}

export interface QuestionInterpretationResult {
  spec: QuestionSpec;
  model?: string;
  usage?: Record<string, unknown>;
}

export interface RunSnapshot {
  run_id: string;
  kind: string;
  status: string;
  created_at: string;
  updated_at: string;
  input: QuestionClarificationPayload;
  event_count: number;
  context: Record<string, unknown>[];
  result?: QuestionClarificationResult;
  error?: string;
}

export interface RunControlResponse extends RunSnapshot {
  run_url: string;
  events_url: string;
}

