const TERMINAL_EVENTS = new Set(["run_succeeded", "run_failed"]);
const RUN_EVENT_TYPES = [
  "run_created",
  "run_started",
  "stage_started",
  "model_call_started",
  "model_call_succeeded",
  "stage_succeeded",
  "run_succeeded",
  "stage_failed",
  "run_failed",
];

@customElement("insight-specialist-app")
export class InsightSpecialistApp extends LitElement {
  @state()
  private status = "idle";

  @state()
  private events: RunEvent[] = [];

  @state()
  private datasetProfile: DatasetProfile | null = null;

  @state()
  private run: RunStartResponse | null = null;

  @state()
  private snapshot: RunSnapshot | null = null;

  @state()
  private error = "";

  @state()
  private activeStep: WizardStep = "define";

  @state()
  private submittedQuestion = "";

  @state()
  private submittedFileName = "";

  @state()
  private clarificationAnswers: ClarificationAnswers | null = null;

  @state()
  private doNotDisturb = loadNotificationPreferences().doNotDisturb;

  private eventSource: EventSource | null = null;

  static styles = unsafeCSS(insightSpecialistAppStyles);

  connectedCallback(): void {
    super.connectedCallback();
    void this.checkDesktopBackend();
  }

  disconnectedCallback(): void {
    this.eventSource?.close();
    super.disconnectedCallback();
  }

  render() {
    return html`
      <div class="shell">
        <main>
          <header>
            <div>
              <h1>Insight Specialist</h1>
              <p class="intro">
                Define the analysis request, answer clarification questions, and watch each step become
                reviewable as the backend moves forward.
              </p>
            </div>
            <label class="preference-toggle">
              <input
                type="checkbox"
                .checked=${this.doNotDisturb}
                @change=${this.handleDoNotDisturbChange}
              />
              <span>Do not disturb</span>
            </label>
          </header>

          <section class="step-map">
            <process-map .steps=${this.processSteps} @wizard-step-select=${this.handleStepSelect}></process-map>
          </section>

          <section class="panel">
            ${this.activeStep === "define" ? this.renderDefineStep() : null}
            ${this.activeStep === "clarify" ? this.renderClarifyStep() : null}
            ${this.activeStep === "interpret" ? this.renderInterpretStep() : null}
          </section>

          ${this.error ? html`<div class="error" role="alert">${this.error}</div>` : null}

          <section>
            <run-feedback-panel
              .status=${this.status}
              .events=${this.events}
              .datasetProfile=${this.datasetProfile}
            ></run-feedback-panel>
          </section>
        </main>

        <response-panel .snapshot=${this.snapshot}></response-panel>
      </div>
    `;
  }

  private renderDefineStep() {
    if (this.snapshot) {
      return html`
        <div class="review">
          <h2>Define the question</h2>
          <div class="review-row">
