  private async handleSubmit(event: CustomEvent<QuestionRunSubmitDetail>) {
    this.resetRunState();
    this.status = "profiling";
    this.submittedQuestion = event.detail.question;
    this.submittedFileName = event.detail.dataFile.name;

    try {
      const datasetProfile = buildDatasetProfileFromCsvText(event.detail.dataFile.text);
      this.datasetProfile = datasetProfile;
      this.status = "queued";

      const run = await startQuestionClarificationRun({
        raw_question: event.detail.question,
        dataset_profile: datasetProfile,
      });
      this.run = run;
      this.status = run.status;
      await this.openEventStream(run);
    } catch (error) {
      this.status = "failed";
      this.error = error instanceof Error ? error.message : "Could not start the run.";
    }
  }

  private async checkDesktopBackend() {
    try {
      await resolveApiBaseUrl();
    } catch (error) {
      this.status = "failed";
      this.error = error instanceof Error ? error.message : "Could not connect to the local backend.";
    }
  }

  private async openEventStream(run: RunStartResponse) {
    await this.openEventStreamAfter(run, 0);
  }

  private async openEventStreamAfter(run: Pick<RunStartResponse, "events_url" | "run_url">, afterEventId: number) {
    this.eventSource?.close();
    const eventsUrl = afterEventId > 0 ? `${run.events_url}?after=${afterEventId}` : run.events_url;
    this.eventSource = new EventSource(await toResolvedApiUrl(eventsUrl));

    for (const type of RUN_EVENT_TYPES) {
      this.eventSource.addEventListener(type, (message) => {
        const event = JSON.parse((message as MessageEvent).data) as RunEvent;
        this.events = [...this.events, event];
        this.status = statusFromEvent(event, this.status);
        this.updateActiveStepFromEvent(event);
        if (TERMINAL_EVENTS.has(event.type)) {
          this.eventSource?.close();
          void this.loadSnapshot(run.run_url);
        }
      });
    }

    this.eventSource.onerror = () => {
      if (this.status !== "succeeded" && this.status !== "failed") {
        this.error = "Lost the run event stream. The local backend may have stopped.";
      }
    };
  }

  private async loadSnapshot(runUrl: string) {
    try {
      this.snapshot = await getRunSnapshot(runUrl);
      this.status = this.snapshot.status;
      if (this.snapshot.result?.question_interpretation) {
        this.activeStep = "interpret";
      } else if (this.snapshot.result?.spec.should_ask_user) {
        this.activeStep = "clarify";
      }
      if (this.snapshot.error) {
        this.error = this.snapshot.error;
      }
    } catch (error) {
      this.status = "failed";
      this.error = error instanceof Error ? error.message : "Could not load the run result.";
    }
  }

  private resetRunState() {
    this.eventSource?.close();
    this.eventSource = null;
    this.events = [];
    this.run = null;
    this.snapshot = null;
    this.error = "";
    this.clarificationAnswers = null;
    this.activeStep = "define";
  }

  private updateActiveStepFromEvent(event: RunEvent) {
    if (event.type !== "stage_started" && event.type !== "model_call_started") return;
    const step = stepFromStage(event.payload.stage);
    if (step) this.activeStep = step;
  }

  private handleStepSelect(event: CustomEvent<{ step: WizardStep }>) {
    this.activeStep = event.detail.step;
  }

  private async handleClarificationAnswers(event: CustomEvent<{ answers: ClarificationAnswers }>) {
    if (!this.run) {
      this.error = "No active run is available for these clarification answers.";
      return;
    }
    const afterEventId = this.snapshot?.event_count ?? this.events.length;
    this.clarificationAnswers = event.detail.answers;
    this.status = "running";
    this.error = "";
    try {
      const response = await submitClarificationAnswers(this.run.run_id, {
        answers: event.detail.answers,
      });
      this.snapshot = response;
      await this.openEventStreamAfter(response, afterEventId);
    } catch (error) {
      this.status = "failed";
      this.error = error instanceof Error ? error.message : "Could not submit clarification answers.";
    }
  }

  private handleDoNotDisturbChange(event: Event) {
    const input = event.currentTarget as HTMLInputElement;
    this.doNotDisturb = input.checked;
    saveNotificationPreferences({ doNotDisturb: this.doNotDisturb });
  }

  private get processSteps(): ProcessMapStep[] {
    const defineComplete = Boolean(this.run ?? this.snapshot);
    const clarifyAvailable = Boolean(this.run ?? this.snapshot?.result?.spec);
    const clarifyComplete = Boolean(this.clarificationAnswers);
    const interpretationAvailable = this.activeStep === "interpret" || Boolean(this.snapshot?.result?.question_interpretation);
    return [
      {
        id: "define",
        label: "Define question",
        status: defineComplete && this.activeStep !== "define" ? "completed" : this.activeStep === "define" ? "current" : "future",
        clickable: this.activeStep === "define" || defineComplete,
      },
      {
        id: "clarify",
        label: "Clarify intent",
        status: clarifyComplete ? "completed" : this.activeStep === "clarify" ? "current" : "future",
        clickable: clarifyAvailable,
      },
      {
        id: "interpret",
        label: "Interpret question",
        status: this.activeStep === "interpret" ? "current" : "future",
        clickable: interpretationAvailable,
      },
    ];
  }
}

function stepFromStage(stage: unknown): WizardStep | null {
  if (stage === "question_clarification") return "clarify";
  if (stage === "question_interpretation") return "interpret";
  return null;
}

function statusFromEvent(event: RunEvent, fallback: string): string {
  if (event.type === "run_started" || event.type === "stage_started" || event.type === "model_call_started") {
    return "running";
  }
  if (event.type === "run_succeeded") return "succeeded";
  if (event.type === "run_failed" || event.type === "stage_failed") return "failed";
  return fallback;
}

