@customElement("clarification-step")
export class ClarificationStep extends LitElement {
  @property({ attribute: false })
  spec: QuestionClarificationSpec | null = null;

  @property({ attribute: false })
  capturedAnswers: ClarificationAnswers | null = null;

  @state()
  private draftAnswers: ClarificationAnswers = {};

  @state()
  private error = "";

  static styles = unsafeCSS(styles);

  render() {
    const spec = this.spec;
    if (!spec) {
      return html`
        <h2>Clarify intent</h2>
        <p class="empty">Submit the first step to see clarification questions.</p>
      `;
    }

    const blockingQuestions = spec.unanswered_questions.filter((question) => question.blocking);
    if (blockingQuestions.length === 0) {
      return html`
        <h2>Clarify intent</h2>
        <p class="success">No blocking clarification questions were returned.</p>
        ${this.renderDefaults(spec)}
      `;
    }

    if (this.capturedAnswers) {
      return html`
        <h2>Clarify intent</h2>
        <p class="success">Clarification answers captured. The next step will use these answers to interpret the question.</p>
        <div class="captured">
          ${blockingQuestions.map(
            (question) => html`
              <div class="answer-item">
                <div class="field">${question.question}</div>
                <div>${this.capturedAnswers?.[question.id]}</div>
              </div>
            `,
          )}
        </div>
        ${this.renderDefaults(spec)}
      `;
    }

    return html`
      <h2>Clarify intent</h2>
      <p class="intro">Answer the blocking questions so the analysis can continue with the right assumptions.</p>
      <div class="questions">
        ${blockingQuestions.map(
          (question) => html`
            <label>
              ${question.question}
              <span class="reason">${question.reason}</span>
              <textarea
                name=${`answer-${question.id}`}
                .value=${this.draftAnswers[question.id] ?? ""}
                @input=${(event: Event) => this.updateAnswer(question.id, event)}
              ></textarea>
            </label>
          `,
        )}
      </div>
      ${this.renderDefaults(spec)}
      <div class="actions">
        <button type="button" @click=${() => this.submitAnswers(blockingQuestions.map((question) => question.id))}>
          Continue
        </button>
        ${this.error ? html`<span class="error" role="alert">${this.error}</span>` : null}
      </div>
    `;
  }

  private renderDefaults(spec: QuestionClarificationSpec) {
    if (spec.non_blocking_defaults.length === 0) return null;
    return html`
      <div class="defaults">
        <h3>Defaults</h3>
        ${spec.non_blocking_defaults.map(
          (item) => html`
            <div class="default-item">
              <div class="field">${item.field}: ${item.default}</div>
              <div class="reason">${item.reason}</div>
            </div>
          `,
        )}
      </div>
    `;
  }

  private updateAnswer(questionId: string, event: Event) {
    this.draftAnswers = {
      ...this.draftAnswers,
      [questionId]: (event.target as HTMLTextAreaElement).value,
    };
    this.error = "";
  }

  private submitAnswers(questionIds: string[]) {
    const answers = Object.fromEntries(
      questionIds.map((questionId) => [questionId, this.draftAnswers[questionId]?.trim() ?? ""]),
    );
    const missingAnswer = questionIds.some((questionId) => !answers[questionId]);
    if (missingAnswer) {
      this.error = "Answer each blocking question before continuing.";
      return;
    }

    this.error = "";
    this.dispatchEvent(
      new CustomEvent<{ answers: ClarificationAnswers }>("clarification-answers-submit", {
        detail: { answers },
        bubbles: true,
        composed: true,
      }),
    );
  }
}

