fn wait_for_backend_health_with<F>(
    base_url: &str,
    timeout: Duration,
    poll_interval: Duration,
    mut health: F,
) -> Result<(), String>
where
    F: FnMut(&str) -> Result<(), String>,
{
    let started_at = Instant::now();
    let mut last_error = "health check did not run".to_owned();

    while started_at.elapsed() <= timeout {
        match health(base_url) {
            Ok(()) => return Ok(()),
            Err(error) => last_error = error,
        }
        thread::sleep(poll_interval);
    }

    Err(last_error)
}

fn backend_health(base_url: &str) -> Result<(), String> {
    let endpoint = parse_http_endpoint(base_url)?;
    let address = (endpoint.host.as_str(), endpoint.port)
        .to_socket_addrs()
        .map_err(|error| {
            format!(
                "could not resolve {}:{}: {error}",
                endpoint.host, endpoint.port
            )
        })?
        .next()
        .ok_or_else(|| format!("could not resolve {}:{}", endpoint.host, endpoint.port))?;
    let mut stream =
        TcpStream::connect_timeout(&address, Duration::from_millis(500)).map_err(|error| {
            format!(
                "could not connect to {}:{}: {error}",
                endpoint.host, endpoint.port
            )
        })?;
    stream
        .set_read_timeout(Some(Duration::from_millis(500)))
        .map_err(|error| format!("could not set read timeout: {error}"))?;
    stream
        .set_write_timeout(Some(Duration::from_millis(500)))
        .map_err(|error| format!("could not set write timeout: {error}"))?;

    let request = format!(
        "GET /health HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n",
        endpoint.host
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|error| format!("could not write health request: {error}"))?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|error| format!("could not read health response: {error}"))?;

    if health_response_is_ok(&response) {
        Ok(())
    } else {
        Err("GET /health returned a non-200 response".to_owned())
    }
}

