import {
  createQuestionClarificationMockBackend,
  deepElement,
  deepText,
  startDesktopUiHarness,
} from "./harness.mjs";

let backend;
let driver;
let harness;

describe("question clarification frontend slice", () => {
  before(async () => {
    backend = createQuestionClarificationMockBackend({ eventStreamStartDelayMs: 500 });
    harness = await startDesktopUiHarness({ backend });
    driver = harness.driver;
  });

  after(async () => {
    if (harness) await harness.close();
  });

  it("starts a mocked question-clarification run from the browser UI", async () => {
    const csvPath = await writeChurnCsv("start-run");

    await submitQuestionRun("What caused customers to cancel?", csvPath);

    await driver.waitUntil(async () => Boolean(backend.lastRunRequest), { timeout: 5_000 });
    assert.equal(backend.lastRunRequest.raw_question, "What caused customers to cancel?");
    assert.equal(backend.lastRunRequest.dataset_profile.row_count, 2);
    assert.deepEqual(
      backend.lastRunRequest.dataset_profile.columns.map((column) => [column.name, column.detected_type]),
      [
        ["customer_id", "string"],
        ["signup_date", "date"],
        ["canceled", "boolean"],
        ["revenue", "numeric"],
      ],
    );

    await driver.waitUntil(async () => /Status\s*(queued|running)/.test(await deepText(driver)), {
      timeout: 5_000,
    });
    const pageText = await deepText(driver);
    assert.doesNotMatch(pageText, /Status\s*idle/);
    assert.doesNotMatch(pageText, /Status\s*profiling/);
    assert.match(pageText, /Question clarification/);
    assert.match(pageText, /Queued|The backend is clarifying the question/);
  });

  it("renders clarification questions and defaults, submits answers, and resumes interpretation", async () => {
    const csvPath = await writeChurnCsv("churn");

    await submitQuestionRun("What caused customers to cancel?", csvPath);

    await driver.waitUntil(async () => (await deepText(driver)).includes("run_succeeded"), { timeout: 10_000 });
    await driver.waitUntil(
      async () => (await deepText(driver)).includes("What period should I analyze?"),
      { timeout: 10_000 },
    );

    const pageText = await deepText(driver);
    assert.match(pageText, /2 rows/);
    assert.match(pageText, /Model calls\s*1/);
    assert.match(pageText, /Can proceed:\s*No/);
    assert.match(pageText, /Do you need causal proof/);
    assert.match(pageText, /report_format\s*:\s*html/);
    assert.match(pageText, /association_or_risk_factors/);
    assert.match(pageText, /Clarify intent/);

    const timePeriodAnswer = await deepElement(driver, [
      "insight-specialist-app",
      "clarification-step",
      "textarea[name='answer-time_period']",
    ]);
    await timePeriodAnswer.setValue("Use cancellations from the last 6 months.");

    const causalStandardAnswer = await deepElement(driver, [
      "insight-specialist-app",
      "clarification-step",
      "textarea[name='answer-causal_standard']",
    ]);
    await causalStandardAnswer.setValue("A ranked list of associated risk factors is acceptable.");

    const continueButton = await deepElement(driver, ["insight-specialist-app", "clarification-step", "button"]);
    await continueButton.click();
    await driver.waitUntil(
      async () => (await deepText(driver)).includes("Clarification answers captured"),
      { timeout: 10_000 },
    );
    await driver.waitUntil(async () => (await deepText(driver)).includes("churn_driver_analysis"), { timeout: 10_000 });

    const defineStep = await deepElement(driver, ["insight-specialist-app", "process-map", "button"]);
    await defineStep.click();
    const reviewText = await deepText(driver);
    assert.match(reviewText, /Define the question/);
    assert.match(reviewText, /churn.csv/);
    assert.equal(backend.lastAnswersRequest.answers.time_period, "Use cancellations from the last 6 months.");
    assert.equal(
      backend.lastAnswersRequest.answers.causal_standard,
      "A ranked list of associated risk factors is acceptable.",
    );
    assert.equal(backend.lastRunRequest.raw_question, "What caused customers to cancel?");
    assert.equal(backend.lastRunRequest.dataset_profile.row_count, 2);
    assert.deepEqual(
      backend.lastRunRequest.dataset_profile.columns.map((column) => [column.name, column.detected_type]),
      [
        ["customer_id", "string"],
        ["signup_date", "date"],
        ["canceled", "boolean"],
        ["revenue", "numeric"],
      ],
    );
  });

  it("updates the process map and feedback panel from mocked SSE run events", async () => {
    const csvPath = await writeChurnCsv("sse-progress");
    const previousTiming = backend.setEventTiming({ eventDelayMs: 300 });

    try {
      await submitQuestionRun("What caused customers to cancel?", csvPath);

      await driver.waitUntil(async () => (await deepText(driver)).includes("stage_started"), { timeout: 10_000 });
      const liveStates = await processMapStates();
      const liveStageFeedback = await deepText(driver);
      assert.deepEqual(
        liveStates.map((step) => [step.label, step.status, step.current]),
        [
          ["Define question", "completed", false],
          ["Clarify intent", "current", true],
          ["Interpret question", "future", false],
        ],
      );
      assert.match(liveStageFeedback, /run_started/);
      assert.match(liveStageFeedback, /stage_started/);
      assert.match(liveStageFeedback, /Status\s*running/);

      await driver.waitUntil(async () => (await deepText(driver)).includes("model_call_started"), { timeout: 10_000 });
      await driver.waitUntil(async () => /Model calls\s*1/.test(await deepText(driver)), { timeout: 10_000 });
      const liveFeedback = await deepText(driver);
      assert.match(liveFeedback, /model_call_started/);
      assert.match(liveFeedback, /Model calls\s*1/);

      await driver.waitUntil(async () => (await deepText(driver)).includes("stage_succeeded"), { timeout: 10_000 });
      await driver.waitUntil(async () => (await deepText(driver)).includes("run_succeeded"), { timeout: 10_000 });
      await driver.waitUntil(async () => /Status\s*succeeded/.test(await deepText(driver)), { timeout: 10_000 });

      const terminalFeedback = await deepText(driver);
      assert.match(terminalFeedback, /Clarification completed/);
      assert.doesNotMatch(terminalFeedback, /Status\s*running/);
    } finally {
      backend.setEventTiming(previousTiming);
    }
  });
});

async function writeChurnCsv(name) {
  const tempDir = await mkdtemp(path.join(tmpdir(), "insight-specialist-ui-"));
  const csvPath = path.join(tempDir, `${name}.csv`);
  await writeFile(
    csvPath,
    [
      "customer_id,signup_date,canceled,revenue",
      "c1,2024-01-01,true,19.99",
      "c2,2024-02-01,false,49.50",
    ].join("\n"),
  );
  return csvPath;
}

async function submitQuestionRun(question, csvPath) {
  await driver.url(harness.baseUrl);

  const textarea = await deepElement(driver, ["insight-specialist-app", "question-run-form", "textarea[name='question']"]);
  await textarea.setValue(question);

  const fileInput = await deepElement(driver, ["insight-specialist-app", "question-run-form", "input[type='file']"]);
  await fileInput.setValue(csvPath);

  const submit = await deepElement(driver, ["insight-specialist-app", "question-run-form", "button[type='submit']"]);
  await submit.click();
}

async function processMapStates() {
  return await driver.execute(() => {
    const app = document.querySelector("insight-specialist-app");
    const processMap = app?.shadowRoot?.querySelector("process-map");
    const buttons = [...(processMap?.shadowRoot?.querySelectorAll("button") ?? [])];
    return buttons.map((button) => ({
      label: button.textContent.trim().replace(/\s+/g, " ").replace(/^\S+\s/, ""),
      status: button.className,
      current: button.getAttribute("aria-current") === "step",
      disabled: button.disabled,
    }));
  });
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import {
  isTauriRuntime,
  clearBackendUrlCache,
  resolveApiBaseUrl,
  startQuestionClarificationRun,
  submitClarificationAnswers,
  toApiUrl,
  toResolvedApiUrl,
} from "../../src/api";

vi.mock("@tauri-apps/api/core", () => ({
  invoke: vi.fn(),
}));

const mockedInvoke = vi.mocked(invoke);

beforeEach(() => {
  clearBackendUrlCache();
  mockedInvoke.mockReset();
  delete (globalThis as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__;
});

afterEach(() => {
  delete (globalThis as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__;
});

describe("toApiUrl", () => {
  it("prefixes backend paths for the Vite proxy", () => {
    expect(toApiUrl("/runs/abc/events")).toBe("/api/runs/abc/events");
    expect(toApiUrl("runs/abc")).toBe("/api/runs/abc");
  });

  it("does not double prefix api paths", () => {
    expect(toApiUrl("/api/runs/abc")).toBe("/api/runs/abc");
  });

  it("joins backend URLs supplied by the Tauri shell", () => {
    expect(toApiUrl("/runs/abc/events", "http://127.0.0.1:8765/")).toBe(
      "http://127.0.0.1:8765/runs/abc/events",
    );
    expect(toApiUrl("/api/runs/abc/events", "http://127.0.0.1:8765")).toBe(
      "http://127.0.0.1:8765/runs/abc/events",
    );
  });

  it("leaves absolute backend URLs unchanged", () => {
    expect(toApiUrl("http://127.0.0.1:8765/runs/abc", "http://localhost:9999")).toBe(
      "http://127.0.0.1:8765/runs/abc",
    );
  });
});

describe("resolveApiBaseUrl", () => {
  it("uses the Vite proxy path outside Tauri", async () => {
    await expect(resolveApiBaseUrl()).resolves.toBe("/api");

    expect(isTauriRuntime()).toBe(false);
    expect(mockedInvoke).not.toHaveBeenCalled();
  });

  it("uses and caches the backend URL provided by Tauri", async () => {
    (globalThis as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__ = {};
    mockedInvoke.mockResolvedValue("http://127.0.0.1:8765/");

    await expect(resolveApiBaseUrl()).resolves.toBe("http://127.0.0.1:8765");
    await expect(toResolvedApiUrl("/runs/run-1")).resolves.toBe("http://127.0.0.1:8765/runs/run-1");

    expect(isTauriRuntime()).toBe(true);
    expect(mockedInvoke).toHaveBeenCalledTimes(1);
    expect(mockedInvoke).toHaveBeenCalledWith("get_backend_url");
  });

  it("surfaces Tauri sidecar startup failures", async () => {
    (globalThis as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__ = {};
    mockedInvoke.mockRejectedValue(new Error("Could not start the local backend sidecar."));

    await expect(resolveApiBaseUrl()).rejects.toThrow("Could not start the local backend sidecar.");
  });
});

describe("startQuestionClarificationRun", () => {
  it("surfaces backend proxy details when the dev backend is unreachable", async () => {
    const fetchImpl = async () =>
      new Response(
        JSON.stringify({
          detail: "Local backend is not reachable at http://127.0.0.1:8765.",
        }),
        { status: 502, headers: { "Content-Type": "application/json" } },
      );

    await expect(
      startQuestionClarificationRun(
        {
          raw_question: "What causes customers to cancel?",
          dataset_profile: {
            row_count: 1,
            column_count: 1,
            columns: [{ name: "canceled", detected_type: "boolean" }],
          },
        },
        fetchImpl as typeof fetch,
      ),
    ).rejects.toThrow("Local backend is not reachable at http://127.0.0.1:8765.");
  });

  it("surfaces direct backend network failures with the backend target", async () => {
    (globalThis as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__ = {};
    mockedInvoke.mockResolvedValue("http://127.0.0.1:8765");
    const fetchImpl = async () => {
      throw new TypeError("fetch failed");
    };

    await expect(
      startQuestionClarificationRun(
        {
          raw_question: "What causes customers to cancel?",
          dataset_profile: {
            row_count: 1,
            column_count: 1,
            columns: [{ name: "canceled", detected_type: "boolean" }],
          },
        },
        fetchImpl as typeof fetch,
      ),
    ).rejects.toThrow("Local backend is not reachable at http://127.0.0.1:8765. fetch failed");
  });
});

describe("submitClarificationAnswers", () => {
  it("posts answers to the run clarification endpoint", async () => {
    let requestedUrl = "";
    let requestedBody = "";
    const fetchImpl = async (url: RequestInfo | URL, init?: RequestInit) => {
      requestedUrl = String(url);
      requestedBody = String(init?.body);
      return new Response(
        JSON.stringify({
          run_id: "run-1",
          kind: "question_clarification",
          status: "running",
          created_at: "2026-05-21T00:00:00Z",
          updated_at: "2026-05-21T00:00:01Z",
          input: { raw_question: "Why?", dataset_profile: { row_count: 1, column_count: 1, columns: [] } },
          event_count: 8,
          context: [],
          run_url: "/runs/run-1",
          events_url: "/runs/run-1/events",
        }),
        { status: 202, headers: { "Content-Type": "application/json" } },
      );
    };

    const response = await submitClarificationAnswers(
      "run-1",
      { answers: { time_period: "Use the last 6 months." } },
      fetchImpl as typeof fetch,
    );

    expect(requestedUrl).toBe("/api/runs/run-1/clarification-answers");
    expect(JSON.parse(requestedBody)).toEqual({ answers: { time_period: "Use the last 6 months." } });
    expect(response.status).toBe("running");
  });
});
